import{_ as a,o as d,c as r,a3 as e}from"./chunks/framework.qCVWde4n.js";const u=JSON.parse('{"title":"功能接入总览","description":"","frontmatter":{},"headers":[],"relativePath":"features/start.md","filePath":"features/start.md","lastUpdated":1791297320000}'),o={name:"features/start.md"};function s(n,t,l,c,h,i){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="功能接入总览" tabindex="-1">功能接入总览 <a class="header-anchor" href="#功能接入总览" aria-label="Permalink to &quot;功能接入总览&quot;">​</a></h1><p>框架能改的东西分几大类。本篇是总目录，帮你找到该看哪页。</p><h2 id="能力总览" tabindex="-1">能力总览 <a class="header-anchor" href="#能力总览" aria-label="Permalink to &quot;能力总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分类</th><th>具体能力</th><th>详细文档</th></tr></thead><tbody><tr><td><strong>数值</strong></td><td>主炮、鱼雷、防空、航弹、传感器、经济、AI、航空</td><td><a href="/AtlanticFleetSite/docs/features/params">参数系统</a></td></tr><tr><td><strong>战斗</strong></td><td>伤害倍率、命中、装填、射程</td><td><a href="/AtlanticFleetSite/docs/features/combat">战斗数值</a></td></tr><tr><td><strong>经济</strong></td><td>威望收入、修理成本</td><td><a href="/AtlanticFleetSite/docs/features/economy">经济与威望</a></td></tr><tr><td><strong>感知</strong></td><td>雷达/声呐范围、侦察</td><td><a href="/AtlanticFleetSite/docs/features/sensor-air">传感器与航空</a></td></tr><tr><td><strong>AI</strong></td><td>敌方行为、难度</td><td><a href="/AtlanticFleetSite/docs/features/ai">AI 行为</a></td></tr><tr><td><strong>调试</strong></td><td>全局倍速、瞬间修理、解锁、开局资源</td><td><a href="/AtlanticFleetSite/docs/features/sandbox">沙盒与调试开关</a></td></tr><tr><td><strong>内容</strong></td><td>自定义舰船</td><td><a href="/AtlanticFleetSite/docs/features/ships">自定义舰船</a></td></tr><tr><td><strong>内容</strong></td><td>自定义编队</td><td><a href="/AtlanticFleetSite/docs/features/fleets">自定义编队</a></td></tr><tr><td><strong>内容</strong></td><td>自制 3D 模型</td><td><a href="/AtlanticFleetSite/docs/features/models">自制模型</a></td></tr><tr><td><strong>分发</strong></td><td>分享码、账号、热座对战</td><td><a href="/AtlanticFleetSite/docs/features/profile">玩家档案与本地热座</a></td></tr><tr><td><strong>分发</strong></td><td>分享码机制与交换</td><td><a href="/AtlanticFleetSite/docs/features/sharecode">Mod 分享码</a></td></tr><tr><td><strong>界面</strong></td><td>文本与多语言</td><td><a href="/AtlanticFleetSite/docs/features/i18n">多语言与界面文本</a></td></tr></tbody></table><h2 id="按「我想做什么」查" tabindex="-1">按「我想做什么」查 <a class="header-anchor" href="#按「我想做什么」查" aria-label="Permalink to &quot;按「我想做什么」查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>我想要</th><th>用哪个功能</th></tr></thead><tbody><tr><td>让主炮打得更疼</td><td><a href="/AtlanticFleetSite/docs/features/combat">战斗数值</a> → <code>combat.gun.damageMul</code></td></tr><tr><td>让鱼雷装填更快</td><td><a href="/AtlanticFleetSite/docs/features/combat">战斗数值</a> → <code>combat.torpedo.reloadMul</code></td></tr><tr><td>威望涨得快一点</td><td><a href="/AtlanticFleetSite/docs/features/economy">经济与威望</a> → <code>economy.renownMul</code></td></tr><tr><td>修船不要钱</td><td><a href="/AtlanticFleetSite/docs/features/sandbox">沙盒与调试开关</a> → <code>sandbox.instantRepair</code></td></tr><tr><td>开局就有钱</td><td><a href="/AtlanticFleetSite/docs/features/sandbox">沙盒与调试开关</a> → <code>sandbox.startRenown</code></td></tr><tr><td>声呐看得更远</td><td><a href="/AtlanticFleetSite/docs/features/sensor-air">传感器与航空</a> → <code>sensor.sonarRangeMul</code></td></tr><tr><td>敌人变笨一点</td><td><a href="/AtlanticFleetSite/docs/features/ai">AI 行为</a></td></tr><tr><td>加一艘自己的船</td><td><a href="/AtlanticFleetSite/docs/features/ships">自定义舰船</a></td></tr><tr><td>组一个原版没有的编队</td><td><a href="/AtlanticFleetSite/docs/features/fleets">自定义编队</a></td></tr><tr><td>换掉船的外观模型</td><td><a href="/AtlanticFleetSite/docs/features/models">自制模型</a></td></tr><tr><td>让游戏快进</td><td><a href="/AtlanticFleetSite/docs/features/sandbox">沙盒与调试开关</a> → <code>sandbox.timeScale</code></td></tr><tr><td>把配置给朋友</td><td><a href="/AtlanticFleetSite/docs/features/sharecode">Mod 分享码</a></td></tr></tbody></table><h2 id="三类功能-三种性质" tabindex="-1">三类功能，三种性质 <a class="header-anchor" href="#三类功能-三种性质" aria-label="Permalink to &quot;三类功能，三种性质&quot;">​</a></h2><p>理解这个分类，能帮你判断「这个功能该不该用」。</p><h3 id="一、数值类-安全-随时可回退" tabindex="-1">一、数值类（安全，随时可回退） <a class="header-anchor" href="#一、数值类-安全-随时可回退" aria-label="Permalink to &quot;一、数值类（安全，随时可回退）&quot;">​</a></h3><p>改变量、改倍率。特点：</p><ul><li>用倍率而不是直接写数值 → <strong>原版更新后不会失效</strong></li><li>面板上拖滑块就能改</li><li>改错了「恢复默认」一键清空</li><li>状态页会列出所有偏离</li></ul><p><strong>日常玩就用这类。</strong></p><h3 id="二、内容类-需要配置-但可控" tabindex="-1">二、内容类（需要配置，但可控） <a class="header-anchor" href="#二、内容类-需要配置-但可控" aria-label="Permalink to &quot;二、内容类（需要配置，但可控）&quot;">​</a></h3><p>加舰船、加编队、换模型。特点：</p><ul><li>需要写 <code>mod.json</code>，或者拿到别人的 Mod</li><li>加载失败有兜底（舰船找不到就跳过，模型找不到就回退内置）</li><li>不会因为没有资源就崩游戏</li></ul><p><strong>想扩展内容用这类。</strong></p><h3 id="三、调试类-危险-谨慎" tabindex="-1">三、调试类（<strong>危险，谨慎</strong>） <a class="header-anchor" href="#三、调试类-危险-谨慎" aria-label="Permalink to &quot;三、调试类（**危险，谨慎**）&quot;">​</a></h3><p>全局倍速、瞬间修理、解锁全船。特点：</p><ul><li>会显著改变游戏体验，甚至让它变得没意思</li><li><strong>全局时间缩放绝不跨会话保存</strong>（防止你忘了自己开过，以为游戏坏了）</li><li>状态页有明确警示</li></ul><div class="danger custom-block"><p class="custom-block-title">调试类参数的注意事项</p><p><strong>「全局倍速」（<code>sandbox.timeScale</code>）是最容易让人困惑的一个。</strong></p><p>它会同时加快动画、装填、AI 行动、转场 —— 也就是说，你按了发射之后，整个战斗会「唰」地推进完，看起来像「点了发射后什么都没了」。</p><p>框架对此的处理是：<strong>倍速只在本次运行有效，下次启动强制回到正常速度。</strong> 这样你不会陷入「我明明什么都没调，怎么全变了」的状态。</p><p>如果遇到「点了发射直接跳过」，第一件事就是：<strong>点倍速按钮回到 x1</strong>。</p></div><h2 id="关于「接入」这个词" tabindex="-1">关于「接入」这个词 <a class="header-anchor" href="#关于「接入」这个词" aria-label="Permalink to &quot;关于「接入」这个词&quot;">​</a></h2><p>有些机器人框架说「接入」，是指连外部聊天平台。</p><p>这里的「接入」和别处不太一样：<strong>指把某项游戏能力接到框架的控制之下</strong>。所以下面每一页讲的都是「这项能力怎么被接管、你能怎么调」。</p><p>理解这一点，看文档会更顺。</p><h2 id="功能接入总表" tabindex="-1">功能接入总表 <a class="header-anchor" href="#功能接入总表" aria-label="Permalink to &quot;功能接入总表&quot;">​</a></h2><p>想看每一项的<strong>参数键名 / 取值范围 / 默认值</strong>的完整对照，见 <a href="/AtlanticFleetSite/docs/features/matrix">功能接入总表</a>。</p>',26)])])}const p=a(o,[["render",s]]);export{u as __pageData,p as default};
